```python
import re
from datetime import datetime

_DIGITS = "0123456789"
_BRACKET_RE = re.compile(r"<([^<>]*)>")
_ZIP_PLUS4_RE = re.compile(r"[0-9]{4,5}-[0-9]{4}")
_DATE_FORMATS = ("%Y-%m-%d", "%m/%d/%Y", "%Y-%m-%dT%H:%M:%S")
_OPT_OUT_VALUES = {"y", "yes", "true", "1"}


def _all_ascii_digits(s):
    return all(c in _DIGITS for c in s)


def _normalize_email(raw):
    """Return the normalized email, or "" if it is not valid."""
    s = raw.strip()
    m = _BRACKET_RE.search(s)
    if m:
        s = m.group(1)
    s = s.strip().lower()
    if s.count("@") != 1:
        return ""
    local, domain = s.split("@")
    if domain in ("gmail.com", "googlemail.com"):
        local = local.replace(".", "")
        local = local.split("+", 1)[0]
        domain = "gmail.com"
    if (not local or "." not in domain
            or domain.startswith(".") or domain.endswith(".")):
        return ""
    return f"{local}@{domain}"


def _normalize_phone(raw):
    """Return the normalized 10-digit phone, or "" if it is not valid."""
    s = raw.lower()
    cut = len(s)
    for marker in ("ext", "x", "#"):
        i = s.find(marker)
        if i != -1 and i < cut:
            cut = i
    digits = "".join(c for c in s[:cut] if c in _DIGITS)
    if len(digits) == 11 and digits[0] == "1":
        digits = digits[1:]
    if len(digits) == 10 and digits[0] not in "01":
        return digits
    return ""


def _normalize_zip(raw):
    z = raw.strip()
    if _ZIP_PLUS4_RE.fullmatch(z):
        z = z.split("-", 1)[0]
    if len(z) == 4 and _all_ascii_digits(z):
        z = "0" + z
    if len(z) == 5 and _all_ascii_digits(z):
        return z
    return ""


def _normalize_name(raw):
    s = raw.strip()
    if s.isupper() or s.islower():
        s = s.title()
    return s


def _parse_updated(raw, row_no):
    s = raw.strip()
    for fmt in _DATE_FORMATS:
        try:
            return datetime.strptime(s, fmt)
        except ValueError:
            pass
    raise ValueError(f"row {row_no}: unrecognized 'updated' value {raw!r}")


def _parse_tags(raw):
    tags = set()
    for t in re.split(r"[;,]", raw):
        t = t.strip().lower()
        if t:
            tags.add(t)
    return tags


def _pick(group, field):
    """Pick the value of `field` from the group's rows where it is non-empty.

    Preference: source is "manual", then most recent `updated`, then earliest
    input row.
    """
    cands = [r for r in group if r[field]]
    cands.sort(key=lambda r: r["index"])                  # earliest row last
    cands.sort(key=lambda r: r["updated"], reverse=True)  # most recent first
    cands.sort(key=lambda r: r["source"] != "manual")     # manual first
    return cands[0][field] if cands else ""


def dedupe_contacts(rows):
    # 1. Normalize every row; drop rows with neither a valid email nor phone.
    recs = []
    for idx, row in enumerate(rows):
        email = _normalize_email(row.get("email", ""))
        phone = _normalize_phone(row.get("phone", ""))
        if not email and not phone:
            continue
        recs.append({
            "index": idx,
            "first_name": _normalize_name(row.get("first_name", "")),
            "last_name": _normalize_name(row.get("last_name", "")),
            "zip": _normalize_zip(row.get("zip", "")),
            "email": email,
            "phone": phone,
            "source": row.get("source", "").strip().lower(),
            "tags": _parse_tags(row.get("tags", "")),
            "opted_out": row.get("opted_out", "").strip().lower() in _OPT_OUT_VALUES,
            "updated": _parse_updated(row["updated"], idx),
        })

    # 2. Union-find: same valid email, or same valid phone + same last name.
    n = len(recs)
    parent = list(range(n))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            if ra < rb:
                parent[rb] = ra
            else:
                parent[ra] = rb

    email_first = {}
    phone_first = {}
    for i, r in enumerate(recs):
        if r["email"]:
            if r["email"] in email_first:
                union(i, email_first[r["email"]])
            else:
                email_first[r["email"]] = i
        if r["phone"] and r["last_name"]:
            key = (r["phone"], r["last_name"].lower())
            if key in phone_first:
                union(i, phone_first[key])
            else:
                phone_first[key] = i

    # 3. Group rows by person; dict insertion order gives earliest-row order.
    groups = {}
    for i, r in enumerate(recs):
        groups.setdefault(find(i), []).append(r)

    # 4. Build one output record per person.
    out = []
    for group in groups.values():
        all_tags = set()
        for r in group:
            all_tags |= r["tags"]
        out.append({
            "first_name": _pick(group, "first_name"),
            "last_name": _pick(group, "last_name"),
            "zip": _pick(group, "zip"),
            "email": _pick(group, "email"),
            "phone": _pick(group, "phone"),
            "source": _pick(group, "source"),
            "tags": ";".join(sorted(all_tags)),
            "opted_out": "Y" if any(r["opted_out"] for r in group) else "N",
            "updated": max(r["updated"] for r in group).strftime("%Y-%m-%d"),
        })
    return out
```

Notes:

- **Filter before sending:** The function keeps opted-out people and marks them `opted_out == "Y"`. Filter those out before the send, for example with `[p for p in dedupe_contacts(rows) if p["opted_out"] == "N"]`. Because a person is grouped across all their duplicate rows, one opt-out on any row excludes that person.
- **ZIP+4 interpretation:** I treated "looks like ZIP+4" as 4 or 5 digits, a hyphen, and 4 digits, so "2139-4307" also gets the leading zero. If the data person meant only the exact 5-4 form, change `_ZIP_PLUS4_RE` to `[0-9]{5}-[0-9]{4}`.
- **Phone markers:** The cut happens at the earliest of "ext", "x", or "#", so "ext" is handled correctly even though it contains an "x".
- **Bad dates:** An unparseable `updated` raises a ValueError naming the row, rather than silently sorting that row as oldest. Since the spec says `updated` is always present and valid, this should only fire on a real data problem.
